 public async Task<RepositoryProviderDiscoveryResult> DiscoverAccessibleRepositoriesAsync(Guid projectId,Guid projectEnvironmentId,Guid secretReferenceId,int maxRepositories=100,CancellationToken cancellationToken=default){if(maxRepositories<1||maxRepositories>AbsoluteRepositoryLimit)throw new ArgumentOutOfRangeException(nameof(maxRepositories),$"Repository discovery must be between 1 and {AbsoluteRepositoryLimit} repositories.");using RepositoryCredentialLease credential=await _credentialResolver.ResolveGitHubFineGrainedPatAsync(projectId,projectEnvironmentId,secretReferenceId,cancellationToken);using GitHubJsonResult userResult=await SendJsonAsync(HttpMethod.Get,"user",credential,"user",cancellationToken);string authenticatedLogin=RequiredString(userResult.Document.RootElement,"login");RepositoryRateLimitSnapshot rateLimit=userResult.RateLimit;var repositories=new List<RepositoryProviderRepository>();for(int page=1;repositories.Count<maxRepositories;page++){string path=$"user/repos?per_page={PageSize}&page={page}&affiliation=owner,collaborator,organization_member&sort=full_name&direction=asc";using GitHubJsonResult pageResult=await SendJsonAsync(HttpMethod.Get,path,credential,"repositories",cancellationToken);rateLimit=pageResult.RateLimit;JsonElement root=pageResult.Document.RootElement;if(root.ValueKind!=JsonValueKind.Array)throw Failure(RepositoryProviderErrorCodes.InvalidResponse,"GitHub returned an invalid repository list response.");int count=0;foreach(JsonElement item in root.EnumerateArray()){count++;if(repositories.Count>=maxRepositories)break;string owner=RequiredString(RequiredObject(item,"owner"),"login");string name=RequiredString(item,"name");repositories.Add(await DiscoverRepositoryCoreAsync(owner,name,credential,cancellationToken));}if(count<PageSize||page>=10)break;}return new RepositoryProviderDiscoveryResult(Provider,authenticatedLogin,repositories,rateLimit);}
