 private async Task<RepositoryProviderRepository> DiscoverRepositoryCoreAsync(string owner,string name,RepositoryCredentialLease credential,CancellationToken cancellationToken){RepositoryProviderIdentity identity=CanonicalizeReferenceValue($"{owner}/{name}");string repositoryPath=$"repos/{Escape(identity.Owner)}/{Escape(identity.Name)}";using GitHubJsonResult metadataResult=await SendJsonAsync(HttpMethod.Get,repositoryPath,credential,"repository",cancellationToken);JsonElement metadata=metadataResult.Document.RootElement;string providerRepositoryId=RequiredInt64(metadata,"id").ToString(CultureInfo.InvariantCulture);string canonicalName=RequiredString(metadata,"name");string canonicalOwner=RequiredString(RequiredObject(metadata,"owner"),"login");RepositoryProviderIdentity canonicalIdentity=CanonicalizeReferenceValue($"{canonicalOwner}/{canonicalName}");string defaultBranch=RequiredString(metadata,"default_branch");string visibility=OptionalString(metadata,"visibility")??(OptionalBoolean(metadata,"private")==true?"private":"public");bool archived=OptionalBoolean(metadata,"archived")??false;bool disabled=OptionalBoolean(metadata,"disabled")??false;bool? fork=OptionalBoolean(metadata,"fork");string? description=OptionalString(metadata,"description");bool? userCanPush=TryGetNestedBoolean(metadata,"permissions","push");using GitHubJsonResult branchResult=await SendJsonAsync(HttpMethod.Get,$"repos/{Escape(canonicalIdentity.Owner)}/{Escape(canonicalIdentity.Name)}/branches/{Escape(defaultBranch)}",credential,"branch",cancellationToken);JsonElement branch=branchResult.Document.RootElement;JsonElement commit=RequiredObject(branch,"commit");string headSha=RequiredString(commit,"sha").ToLowerInvariant();ValidateSha(headSha);string? treeSha=TryGetTreeSha(commit);bool? protectedBranch=OptionalBoolean(branch,"protected");string pullsRead=await ProbeReadAsync($"repos/{Escape(canonicalIdentity.Owner)}/{Escape(canonicalIdentity.Name)}/pulls?state=open&per_page=1",credential,cancellat