 private async Task<string> ProbeReadAsync(string path,RepositoryCredentialLease credential,CancellationToken cancellationToken){try{using GitHubJsonResult result=await SendJsonAsync(HttpMethod.Get,path,credential,"capability",cancellationToken);return RepositoryCapabilityStates.Available;}catch(RepositoryProviderException ex)when(ex.Code==RepositoryProviderErrorCodes.PermissionDenied){return RepositoryCapabilityStates.Denied;}catch(RepositoryProviderException ex)when(ex.Code==RepositoryProviderErrorCodes.RepositoryNotFound){return RepositoryCapabilityStates.Unavailable;}}
