 private async Task<GitHubJsonResult> SendJsonAsync(HttpMethod method,string relativePath,RepositoryCredentialLease credential,string resourceKind,CancellationToken cancellationToken){using HttpRequestMessage request=CreateRequest(method,relativePath,credential);HttpResponseMessage response;try{response=await _httpClient.SendAsync(request,HttpCompletionOption.ResponseHeadersRead,cancellationToken);}catch(OperationCanceledException)when(!cancellationToken.IsCancellationRequested){throw Failure(RepositoryProviderErrorCodes.NetworkError,"GitHub did not respond within the configured timeout.");}catch(HttpRequestException){throw Failure(RepositoryProviderErrorCodes.NetworkError,"GitHub could not be reached.");}using(response){RepositoryRateLimitSnapshot rateLimit=ReadRateLimit(response);if(!response.IsSuccessStatusCode)throw MapFailure(response,resourceKind);try{await using Stream stream=await response.Content.ReadAsStreamAsync(cancellationToken);JsonDocument document=await JsonDocument.ParseAsync(stream,cancellationToken:cancellationToken);return new GitHubJsonResult(document,rateLimit);}catch(JsonException){throw Failure(RepositoryProviderErrorCodes.InvalidResponse,"GitHub returned an invalid JSON response.",(int)response.StatusCode);}}}
 private static HttpRequestMessage CreateRequest(HttpMethod method,string relativePath,RepositoryCredentialLease credential){if(string.IsNullOrWhiteSpace(relativePath)||relativePath.Contains("://",StringComparison.Ordinal)||relativePath.Contains('\\')||relativePath.Contains('\r')||relativePath.Contains('\n'))throw Failure(RepositoryProviderErrorCodes.InvalidRepositoryIdentity,"GitHub request path is invalid.");var request=new HttpRequestMessage(method,new Uri(relativePath,UriKind.Relative));request.Headers.Authorization=new AuthenticationHeaderValue("Bearer",credential.Value);request.Headers.Accept.Add(new MediaTypeWithQualityHeaderValue("application/vnd.github+json"));request.Headers.TryAddWithoutValidation("X-GitHub-Api-Version",GitHubApiVersion);request.Headers.UserAgent.ParseAdd("Dynomax/1.19.0");return request;}
 private static RepositoryProviderException MapFailure(HttpResponseMessage response,string resourceKind){int status=(int)response.StatusCode;RepositoryRateLimitSnapshot rateLimit=ReadRateLimit(response);if(response.StatusCode==HttpStatusCode.Unauthorized)return Failure(RepositoryProviderErrorCodes.AuthenticationFailed,"GitHub authentication failed.",status);if(response.StatusCode==HttpStatusCode.Forbidden&&response.Headers.Contains("X-GitHub-SSO"))return Failure(RepositoryProviderErrorCodes.SsoAuthorizationRequired,"GitHub organization authorization is required for this credential.",status);if((status==403||status==429)&&(rateLimit.Remaining==0||rateLimit.RetryAfterSeconds.HasValue))return Failure(RepositoryProviderErrorCodes.RateLimited,"GitHub rate limit reached.",status,RateLimitRetryAt(rateLimit));if(response.StatusCode==HttpStatusCode.Forbidden)return Failure(RepositoryProviderErrorCodes.PermissionDenied,"GitHub denied the requested repository operation.",status);if(response.StatusCode==HttpStatusCode.NotFound)return Failure(RepositoryProviderErrorCodes.RepositoryNotFound,resourceKind=="repository"?"GitHub repository was not found or is not accessible.":"GitHub resource was not found or is not accessible.",status);if(status>=500)return Failure(RepositoryProviderErrorCodes.ProviderUnavailable,"GitHub is temporarily unavailable.",status);return Failure(RepositoryProviderErrorCodes.ProviderError,"GitHub rejected the repository request.",status);}
