 private static RepositoryProviderIdentity CanonicalizeReferenceValue(string value){string input=value?.Trim()??string.Empty;if(input.Length==0)throw Failure(RepositoryProviderErrorCodes.InvalidRepositoryIdentity,"GitHub repository identity is required.");string owner;string name;if(input.StartsWith("https://",StringComparison.OrdinalIgnoreCase)||input.StartsWith("http://",StringComparison.OrdinalIgnoreCase)){if(!Uri.TryCreate(input,UriKind.Absolute,out Uri? uri)||!string.Equals(uri.Scheme,Uri.UriSchemeHttps,StringComparison.OrdinalIgnoreCase)||!string.Equals(uri.Host,"github.com",StringComparison.OrdinalIgnoreCase)||!string.IsNullOrEmpty(uri.UserInfo)||(!uri.IsDefaultPort&&uri.Port!=443)||!string.IsNullOrEmpty(uri.Query)||!string.IsNullOrEmpty(uri.Fragment))throw Failure(RepositoryProviderErrorCodes.InvalidRepositoryIdentity,"Only canonical https://github.com repository URLs are allowed.");string[] segments=uri.AbsolutePath.Split('/',StringSplitOptions.RemoveEmptyEntries);if(segments.Length!=2)throw Failure(RepositoryProviderErrorCodes.InvalidRepositoryIdentity,"GitHub repository URL must contain exactly owner and repository name.");owner=Uri.UnescapeDataString(segments[0]);name=Uri.UnescapeDataString(segments[1]);}else{if(input.Contains("://",StringComparison.Ordinal)||input.Contains('\\')||input.Contains('\r')||input.Contains('\n'))throw Failure(RepositoryProviderErrorCodes.InvalidRepositoryIdentity,"GitHub repository identity is invalid.");string[] segments=input.Split('/',StringSplitOptions.RemoveEmptyEntries|StringSplitOptions.TrimEntries);if(segments.Length!=2)throw Failure(RepositoryProviderErrorCodes.InvalidRepositoryIdentity,"GitHub repository identity must be owner/repository.");owner=segments[0];name=segments[1];}if(name.EndsWith(".git",StringComparison.OrdinalIgnoreCase))name=name[..^4];owner=ValidateOwner(owner);name=ValidateRepositoryName(name);string fullName=$"{owner}/{name}";return new RepositoryProviderIdentity(owner,name,fullName,$"https://github