 private static string ValidateOwner(string value){string owner=value.Trim();if(owner.Length is <1 or >100||owner[0]=='-'||owner[^1]=='-'||owner.Any(c=>!(char.IsAsciiLetterOrDigit(c)||c=='-')))throw Failure(RepositoryProviderErrorCodes.InvalidRepositoryIdentity,"GitHub repository owner is invalid.");return owner;}private static string ValidateRepositoryName(string value){string name=value.Trim();if(name.Length is <1 or >100||name is "." or ".."||name.Any(c=>!(char.IsAsciiLetterOrDigit(c)||c is '-' or '_' or '.')))throw Failure(RepositoryProviderErrorCodes.InvalidRepositoryIdentity,"GitHub repository name is invalid.");return name;}private static string Escape(string value)=>Uri.EscapeDataString(value);private static void ValidateBaseAddress(Uri? baseAddress){if(baseAddress is null||!baseAddress.IsAbsoluteUri||!string.Equals(baseAddress.Scheme,Uri.UriSchemeHttps,StringComparison.OrdinalIgnoreCase)||!string.Equals(baseAddress.Host,"api.github.com",StringComparison.OrdinalIgnoreCase)||!string.IsNullOrEmpty(baseAddress.UserInfo)||(!baseAddress.IsDefaultPort&&baseAddress.Port!=443))throw new InvalidOperationException("GitHub provider base address must be canonical https://api.github.com/.");}private static void ValidateSha(string value){if(value.Length is not(40 or 64)||value.Any(c=>!Uri.IsHexDigit(c)))throw Failure(RepositoryProviderErrorCodes.InvalidResponse,"GitHub returned an invalid commit SHA.");}private static string? TryGetTreeSha(JsonElement commit){if(!commit.TryGetProperty("commit",out JsonElement inner)||inner.ValueKind!=JsonValueKind.Object)return null;if(!inner.TryGetProperty("tree",out JsonElement tree)||tree.ValueKind!=JsonValueKind.Object)return null;string? sha=OptionalString(tree,"sha");if(string.IsNullOrWhiteSpace(sha))return null;sha=sha.ToLowerInvariant();ValidateSha(sha);return sha;}private static JsonElement RequiredObject(JsonElement element,string property){if(!element.TryGetProperty(property,out JsonElement value)||value.ValueKind!=JsonValueKin